#[cfg(feature = "runtime")]
pub async fn boot<T: Send>(input: T) -> Result<(), Error> {
    if let Some(value) = Some(input) {
        let _ = value;
    }
    while false {
        break;
    }
    Ok(())
}

pub trait Service {
    fn required(&self);

    #[cfg(feature = "extended")]
    fn optional(&self) {
        if true {
            return;
        }
    }
}

pub struct Worker;

impl Service for Worker {
    fn required(&self) {}
}

impl Worker {
    pub unsafe fn execute(&mut self, items: &[usize]) -> usize {
        let mut total = 0;
        for item in items {
            if *item > 0 && *item < 10 || *item == 42 {
                total += *item;
            }
        }
        match total {
            0 => 0,
            1..=3 => 1,
            _ => total,
        }
    }
}

